import re
from datetime import datetime

_EPOCH = datetime(1970, 1, 1)
_DATE_FORMATS = ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y")
_TRUE_VALUES = {"y", "yes", "true", "1"}
_ZIP_PLUS4 = re.compile(r"([0-9]{4,5})-[0-9]{4}")


def _norm_email(raw):
    s = (raw or "").strip()
    if "<" in s:
        start = s.index("<")
        end = s.find(">", start + 1)
        if end != -1:
            s = s[start + 1:end]
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "")
            local = local.split("+", 1)[0]
            domain = "gmail.com"
        s = f"{local}@{domain}"
    return s


def _valid_email(s):
    if s.count("@") != 1:
        return ""
    local, domain = s.split("@")
    if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
        return ""
    return s


def _norm_phone(raw):
    s = (raw or "").lower()
    cut = len(s)
    for marker in ("ext", "x", "#"):
        i = s.find(marker)
        if i != -1 and i < cut:
            cut = i
    digits = "".join(c for c in s[:cut] if c in "0123456789")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _norm_zip(raw):
    z = (raw or "").strip()
    m = _ZIP_PLUS4.fullmatch(z)
    if m:
        z = m.group(1)
    if re.fullmatch(r"[0-9]{4}", z):
        z = "0" + z
    return z if re.fullmatch(r"[0-9]{5}", z) else ""


def _norm_name(raw):
    n = (raw or "").strip()
    if n.isupper() or n.islower():
        n = n.title()
    return n


def _parse_updated(raw):
    s = (raw or "").strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None


def _secs(dt):
    # Larger value = more recent. Unparseable dates sort last.
    return (dt - _EPOCH).total_seconds() if dt is not None else float("-inf")


def _parse_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw or "") if t.strip()}


def dedupe_contacts(rows):
    # Normalize every row and drop rows with no valid email or phone.
    recs = []
    for row in rows:
        email = _valid_email(_norm_email(row.get("email")))
        phone = _norm_phone(row.get("phone"))
        if not email and not phone:
            continue
        last = _norm_name(row.get("last_name"))
        source = (row.get("source") or "").strip().lower()
        dt = _parse_updated(row.get("updated"))
        recs.append({
            "idx": len(recs),
            "email": email,
            "phone": phone,
            "first": _norm_name(row.get("first_name")),
            "last": last,
            "last_key": last.lower(),
            "zip": _norm_zip(row.get("zip")),
            "source": source,
            "manual": source == "manual",
            "dt": dt,
            "tags": _parse_tags(row.get("tags")),
            "opted": (row.get("opted_out") or "").strip().lower() in _TRUE_VALUES,
        })

    # Union-find: rows sharing an email, or a phone plus last name, are one person.
    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    first_by_email = {}
    first_by_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in first_by_email:
                union(first_by_email[r["email"]], i)
            else:
                first_by_email[r["email"]] = i
        if r["phone"] and r["last_key"]:
            key = (r["phone"], r["last_key"])
            if key in first_by_phone_last:
                union(first_by_phone_last[key], i)
            else:
                first_by_phone_last[key] = i

    # Group rows; iterating in input order gives groups ordered by earliest row.
    groups = {}
    for i in range(len(recs)):
        groups.setdefault(find(i), []).append(recs[i])

    def pick(members, field):
        cands = [r for r in members if r[field]]
        if not cands:
            return ""
        best = min(cands, key=lambda r: (not r["manual"], -_secs(r["dt"]), r["idx"]))
        return best[field]

    result = []
    for members in groups.values():
        dts = [r["dt"] for r in members if r["dt"] is not None]
        latest = max(dts).strftime("%Y-%m-%d") if dts else ""
        tags = set().union(*(r["tags"] for r in members))
        result.append({
            "first_name": pick(members, "first"),
            "last_name": pick(members, "last"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(r["opted"] for r in members) else "N",
            "updated": latest,
        })
    return result
```

Notes on interpretation:

- **Opt-outs:** `opted_out` is set at the person level, so any row for a person who opted out in any record yields "Y". Filter on `opted_out == "Y"` before the send.
- **ZIP+4:** I accept a 4- or 5-digit prefix before the hyphen, so an Excel-mangled "2139-4307" becomes "02139".
- **Dates:** An `updated` value that matches none of the three formats is treated as the oldest possible. If every row in a group has an unparseable date, `updated` comes out as "".
- **Matching:** Grouping uses union-find keyed on email and on (phone, last name), so it stays fast on a large export. It gives the same result as checking every pair and applying transitivity.
